-- 804: Machining calculators -- every machining cycle-time formula as a real
-- database calculator, wired per operation, replacing the hand-typed templates.
--
-- GENERATED by scripts/generate-machining-calculators-migration.ts from
-- src/modules/bom-items/costing/machining/calculators/machining-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Machining cycle times were computed by formulas held in TypeScript, while the
-- database carried a second, unrelated set of hand-typed "Machining - ..."
-- calculators (fixed +10 mm approach, CEIL, OLE 80 percent, setup 30 percent,
-- 91.6/hr defaults, no lookup links) that no catalog row pointed at. Every
-- Machining row in process_calculator_mappings had calculator_id NULL, so the
-- Edit Process Cost dialog offered other domains calculators, and the dialog and
-- the quote could not agree.
--
-- This migration:
--   1. retires the unused hand-typed machining templates (renamed with
--      " (retired template)" and stamped retired_at; nothing references them);
--   2. creates one global calculator per machining operation whose inputs are
--      CAD measurements and real machining_reference_data lookup values
--      (data_source machining_lookup, source_table/source_field naming the
--      table and column) and whose calculated fields are the formulas the cost
--      engine evaluates -- the engine holds none of its own;
--   3. maps each operation to its calculator for every machine class that
--      performs it (process_calculator_mappings), after the station rows so
--      the station stays each class first catalog row.
--
-- Requires migration 802 (station rows on the engine machine classes).
-- Self-contained, idempotent, post-checked.

BEGIN;

DO $pre$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.process_calculator_mappings
    WHERE process_group = 'Machining' AND operation = '3 Axis Mill' AND machine_class = '3_axis_mill'
  ) THEN
    RAISE EXCEPTION 'migration 804 needs migration 802 applied first (Machining stations still on retired cnc_* classes)';
  END IF;
END
$pre$;

ALTER TABLE public.calculator_fields DROP CONSTRAINT IF EXISTS valid_data_source;
ALTER TABLE public.calculator_fields ADD CONSTRAINT valid_data_source CHECK (
  data_source IS NULL OR data_source IN ('lhr', 'mhr', 'raw_materials', 'processes', 'manual', 'sheet_metal_lookup', 'machining_lookup')
);

ALTER TABLE public.calculators ADD COLUMN IF NOT EXISTS retired_at TIMESTAMPTZ;
ALTER TABLE public.calculators ADD COLUMN IF NOT EXISTS retired_reason TEXT;
COMMENT ON COLUMN public.calculators.retired_at IS
  'Set when a calculator is withdrawn; retired calculators are hidden from calculator pickers but kept so any saved reference still opens.';

UPDATE public.calculators
SET retired_at = now(),
    retired_reason = $q$Hand-typed template with fixed constants and no lookup-table inputs; superseded by the generated machining calculators (migration 804).$q$,
    name = name || ' (retired template)'
WHERE user_id IS NOT NULL
  AND retired_at IS NULL
  AND name IN ($q$CNC Drilling Calculator$q$, $q$Machining - Boring$q$, $q$Machining - Cost Drivers$q$, $q$Machining - Cutoff$q$, $q$Machining - Drilling$q$, $q$Machining - End Milling and Sawing$q$, $q$Machining - Face Milling$q$, $q$Machining - Facing$q$, $q$Machining - Inspection$q$, $q$Machining - Internal Boring$q$, $q$Machining - Knurling$q$, $q$Machining - Laser Cutting$q$, $q$Machining - Manufacturing$q$, $q$Machining - Plasma Cutting$q$, $q$Machining - Plunge Milling$q$, $q$Machining - Reaming$q$, $q$Machining - Slot Milling$q$, $q$Machining - Step Drilling$q$, $q$Machining - Threading$q$, $q$Machining - Turning$q$, $q$Thread Milling Calculator$q$, $q$Thread Tapping Calculator$q$, $q$Turning Cycle time Calculation$q$);

-- Machining - Drilling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Drilling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Drilling$q$, 'process', 'single', false, true, true, $q$Drilled-hole cycle time: CAD hole diameter and depth, cutting speed and feed from tblDrilling for the material and drill construction.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Drilled-hole cycle time: CAD hole diameter and depth, cutting speed and feed from tblDrilling for the material and drill construction.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Hole Diameter$q$, $q$Hole Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Hole Depth$q$, $q$Hole Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Holes$q$, $q$Holes$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblDrilling$q$, $q$cutting_speed_m_min$q$, NULL, 4, true),
    (v_id, $q$Feed$q$, $q$Feed (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblDrilling$q$, $q$feed_mm_rev$q$, NULL, 5, true),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q${Cutting Speed} * 1000 / (pi * {Hole Diameter})$q$, 6, false),
    (v_id, $q$Feed Rate$q$, $q$Feed Rate (mm/min)$q$, $q$calculated$q$, $q$mm/min$q$, NULL, NULL, NULL, $q${Spindle Speed} * {Feed}$q$, 7, false),
    (v_id, $q$Time per Hole$q$, $q$Time per Hole (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Hole Depth} / {Feed Rate} * 60$q$, 8, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Time per Hole} * {Holes}$q$, 9, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Drilling$q$, v_id, $q$Machining - Drilling$q$, true, 700, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

