    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Polygon Depth$q$, $q$Polygon Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Polygons$q$, $q$Polygons$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$RPM$q$, $q$RPM (rpm)$q$, $q$number$q$, $q$rpm$q$, $q$machining_lookup$q$, $q$tblRotaryBroaching$q$, $q$RPM$q$, NULL, 3, true),
    (v_id, $q$Feed$q$, $q$Feed (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblRotaryBroaching$q$, $q$FeedMmPerRev$q$, NULL, 4, true),
    (v_id, $q$Feed Adjustment$q$, $q$Feed Adjustment$q$, $q$number$q$, NULL, $q$machining_lookup$q$, $q$variables$q$, $q$value$q$, NULL, 5, true),
    (v_id, $q$Time per Polygon$q$, $q$Time per Polygon (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Polygon Depth} / ({RPM} * {Feed} * {Feed Adjustment}) * 60$q$, 6, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Time per Polygon} * {Polygons}$q$, 7, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Rotary Broaching$q$, v_id, $q$Machining - Rotary Broaching$q$, true, 721, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

-- Post-check: every calculator exists once, with all its fields and mappings.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Machining - Drilling$q$, 9, 9),
    ($q$Machining - Rough Turning$q$, 14, 6),
    ($q$Machining - Finish Turning$q$, 7, 6),
    ($q$Machining - Parting$q$, 7, 6),
    ($q$Machining - Reaming$q$, 9, 9),
    ($q$Machining - Rigid Tapping$q$, 9, 9),
    ($q$Machining - Jig Boring$q$, 10, 1),
    ($q$Machining - Gun Drilling$q$, 9, 1),
    ($q$Machining - Deep Bore$q$, 9, 1),
    ($q$Machining - Cylindrical Grinding$q$, 16, 1),
    ($q$Machining - Internal Grinding$q$, 16, 1),
    ($q$Machining - Jig Grind$q$, 17, 1),
    ($q$Machining - Surface Grinding$q$, 14, 1),
    ($q$Machining - Keyway Broaching$q$, 12, 1),
    ($q$Machining - Wire EDM$q$, 7, 1),
    ($q$Machining - Deburring$q$, 3, 1),
    ($q$Machining - Index Transfer$q$, 5, 1),
    ($q$Machining - Secondary Setup$q$, 3, 6),
    ($q$Machining - Inspection$q$, 25, 2),
    ($q$Machining - Hobbing$q$, 12, 1),
    ($q$Machining - Shaving$q$, 11, 1),
    ($q$Machining - Rotary Broaching$q$, 7, 9)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.is_active) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 804: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
